+/**
+ * Reads how a rendered grid header actually looks, for the header-row specs.
+ *
+ * jsdom loads no stylesheet, so a class name alone says nothing about the look. This helper builds the
+ * page's real stylesheet the way the app ships it — the ui-kit and file-manager styles, then the app's own
+ * `global.scss` compiled by Sass and Tailwind — and runs a small CSS cascade (layers, `!important`,
+ * specificity, source order, inline styles, inheritance, `var()`) over the rendered DOM. A header passes
+ * or fails on the look it ends up with, whether that comes from a utility class, an arbitrary value, an
+ * app stylesheet rule, an `@utility`, a kit class or an inline style.
+ *
+ * ag-grid's own theme CSS is injected at runtime and is not present in jsdom; the one ag-grid rule the
+ * header specs depend on (its right-aligned column type reverses the label row) is added by hand.
+ */
+import fs from 'node:fs';
+import { createRequire } from 'node:module';
+import path from 'node:path';
+import { fileURLToPath, pathToFileURL } from 'node:url';
+
+import tailwindcss from '@tailwindcss/postcss';
+import postcss, { AtRule, ChildNode, Container, Rule } from 'postcss';
+import * as sass from 'sass';
+
+const require = createRequire(import.meta.url);
+const APP_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../..');
+
+// ---- stylesheet ------------------------------------------------------------------------------------
+
+/** Inherited properties among the ones the specs read; custom properties inherit too. */
+const INHERITED = new Set(['font-size', 'font-weight', 'text-transform', 'letter-spacing', 'text-align']);
+const READ = new Set([...INHERITED, 'justify-content', 'flex-direction']);
+
+interface Declaration {
+  value: string;
+  important: boolean;
+}
+
+interface StyleRule {
+  selectors: string[];
+  declarations: Map<string, Declaration>;
+  /** Index of the cascade layer, or null when unlayered. */
+  layer: number | null;
+  order: number;
+}
+
+export interface PageStyles {
+  rules: StyleRule[];
+  layerCount: number;
+}
+
+const compileAppStylesheet = async (): Promise<string> => {
+  const entry = path.join(APP_DIR, 'src/app/[lang]/global.scss');
+  const compiled = sass.compile(entry, {
+    importers: [
+      {
+        findFileUrl: (url: string) => (url.startsWith('@/') ? pathToFileURL(path.join(APP_DIR, url.slice(2))) : null),
+      },
+    ],
+    silenceDeprecations: ['import'],
+    logger: sass.Logger.silent,
+  });
+  const result = await postcss([tailwindcss({ base: APP_DIR })]).process(compiled.css, { from: entry });
+  return result.css;
+};
+
+/** Flattens nesting: `&` stands for the parent; a child without `&` is a descendant of it. */
+const nestSelectors = (parents: string[], selectors: string[]): string[] => {
+  if (parents.length === 0) return selectors;
+  const parent = parents.length === 1 ? parents[0] : `:is(${parents.join(', ')})`;
+  return selectors.map((selector) =>
+    selector.includes('&') ? selector.replace(/&/g, `:is(${parent})`) : `:is(${parent}) ${selector}`,
+  );
+};
+
+const collectRules = (sheets: string[]): PageStyles => {
+  const layers: string[] = [];
+  const layerIndex = (name: string) => {
+    if (!layers.includes(name)) layers.push(name);
+    return layers.indexOf(name);
+  };
+  const rules: StyleRule[] = [];
+  let order = 0;
+  let anonymous = 0;
+
+  const walk = (container: Container<ChildNode>, parents: string[], layer: string | null) => {
+    container.each((node) => {
+      if (node.type === 'atrule') {
+        const at = node as AtRule;
+        if (at.name === 'layer') {
